void DynamicMetadataProvider::cleanup_fn(void* arg)
{
    DynamicMetadataProvider* provider = static_cast<DynamicMetadataProvider*>(arg);
    provider->cleanup();
}
void DynamicMetadataProvider::cleanup()
{
    if (m_shutdown) {
        return;
    }
    m_lock.lock();
    if (m_cleanupInterval > 0) {
        m_cleanup_wait->wait(m_cleanupTimeout);
    }
    m_lock.unlock();
    m_shutdown = true;
    if (m_cleanup_thread) {
        m_cleanup_thread->join();
        delete m_cleanup_thread;
        m_cleanup_thread = nullptr;
    }
    if (m_cleanup_wait) {
        delete m_cleanup_wait;
        m_cleanup_wait = nullptr;
    }
}
